import { Component, ChangeDetectionStrategy, input, model, computed } from '@angular/core';
import { InputSize } from '../../models';
import { LG, MD, SM } from '../../constants';

@Component({
  selector: 'app-input',
  templateUrl: './input.html',
  styleUrl: './input.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class InputComponent {
  value = model<string>('');
  placeholder = input<string>('');
  label = input<string | null>(null);
  error = input<string | null>(null);

  iconLeft = input<string | null>(null);
  iconRight = input<string | null>(null);

  size = input<InputSize>(MD);
  disabled = input<boolean>(false);

  sizeClassChart = {
    [SM]: 'input--sm',
    [MD]: 'input--md',
    [LG]: 'input--lg',
  } as const;

  sizeClass = computed(() => this.sizeClassChart[this.size()]);

  onChangeValue(value: string) {
    this.value.update(() => value);
  }
}

